class Remote:
    def __init__(self):
        self.vaults={}; self.items={}; self.creates=[]; self.fills=[]; self.deleted=[]
        self.fill_mode='success'; self.create_mode='success'; self.gets=[]

    def get_vault(self,name):return deepcopy(self.vaults.get(name))

    def create_vault(self,name):
        result={'id':'vault-'+str(len(self.vaults)+1),'name':name}
        self.vaults[name]=result
        return deepcopy(result)

    def create_credential(self,vault,key,fields,**kwargs):
        self.creates.append((vault,key))
        if self.create_mode=='timeout':raise TimeoutError('fixture unknown create outcome')
        definitions=[{name:value for name,value in field.items() if name!='value'} for field in fields]
        values={field['name']:{'has_value':'value' in field,
                **({'value':field['value']} if 'value' in field else {})} for field in fields}
        ready=all(values[field['name']]['has_value'] for field in fields if field.get('required',True))
        result={'id':'credential-'+str(len(self.creates)),'key':key,'version':1,'type':'credential',
                'spec':{'provider':'kernel','fields':deepcopy(definitions)},
                'state':{'provider':'kernel','status':'ready' if ready else 'pending_collection','fields':values},
                'available_operations':[{'type':'collect'},{'type':'fill'}]}
        self.items[vault,key]=result
        return deepcopy(result)

    def get_credential(self,vault,key,**kwargs):
        self.gets.append((vault,key))
        result=deepcopy(self.items.get((vault,key)))
        if result:
            public={field['name'] for field in result['spec']['fields']
                    if field.get('sensitive') is False and field['type'] in {'text','email'}}
            for name,state in result['state']['fields'].items():
                if not kwargs.get('include_public_values') or name not in public:state.pop('value',None)
        return result

    def ready(self,vault,key,version=2):
        item=self.items[vault,key]; item['version']=version; item['state']['status']='ready'
        item['state']['fields']={field['name']:{'has_value':True} for field in item['spec']['fields']}
        return deepcopy(item)

    def collect(self,vault,key):
        return self.get_credential(vault,key)|{'action':{'name':'collect',
            'url':'https://vault.kernel.sh/private-fixture-capability','expires_at':'2099-01-01T00:00:00Z'}}

    def fill(self,vault,key,**kwargs):
        self.fills.append((vault,key,deepcopy(kwargs)))
        if self.fill_mode=='timeout':raise TimeoutError('opaque-fixture-code-never-returned')
        fields=kwargs['fields']
        if self.fill_mode=='partial':
            return {'status':'failed','fields':[{'index':i,'status':'filled' if i==0 else 'failed'} for i in range(len(fields))]}
        if self.fill_mode=='rejected':
            return {'status':'failed','fields':[{'index':i,'status':'failed'} for i in range(len(fields))]}
        return {'status':'completed','fields':[{'index':i,'status':'filled'} for i in range(len(fields))]}

    def delete_credential(self,vault,key):
        self.deleted.append((vault,key)); self.items.pop((vault,key),None); return True


